Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)
OPTIONAL MATCH (a)-[:MENTIONS]->(e)
WHERE (pub:`Publisher OR pub`:Organization)
  AND (
    (
      (toLower(pub.name) CONTAINS 'business today' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'business today'))
      AND any(term IN ['italian', 'cuisine'] WHERE toLower(a.name) CONTAINS term OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS term) OR toLower(coalesce(e.name, '')) CONTAINS term OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS term))
      AND any(term IN ['military', 'conflict', 'war'] WHERE toLower(a.name) CONTAINS term OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS term) OR toLower(coalesce(e.name, '')) CONTAINS term OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS term))
    )
    OR
    (
      (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
      AND any(term IN ['sbf', 'sam bankman-fried'] WHERE toLower(a.name) CONTAINS term OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS term) OR toLower(coalesce(e.name, '')) CONTAINS term OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS term))
      AND any(term IN ['legal', 'strategy', 'argument'] WHERE toLower(a.name) CONTAINS term OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS term) OR toLower(coalesce(e.name, '')) CONTAINS term OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS term))
    )
  )
RETURN DISTINCT a.name AS article, pub.name AS publisher, a.published_on AS published_on
